-- phan_loai: van_phong=1,sinh_vien=2,gaming=3,do_hoa=4,ky_thuat=5,macbook=6,laptop_cu=7
INSERT INTO san_pham_phan_loai (san_pham_id, phan_loai_id) VALUES
-- Acer Aspire 5: văn phòng + sinh viên (phổ thông giá rẻ)
(6, 1), (6, 2),
