-- Legion 5 Pro: gaming (AMD Ryzen + RTX, màn WQXGA)
(8, 3),
-- HP Pavilion 15: văn phòng + sinh viên (đa màu, giá phải chăng)
(9, 1), (9, 2),
-- Dell XPS 15: đồ họa + kỹ thuật (OLED 3.5K, thiết kế cao cấp)
(10, 4), (10, 5),
